# Rebuild ZIP archives
art_dir = r'C:\Users\PREMCHANDYADAV\.gemini\antigravity\brain\d53ad909-c2a8-4f5d-80be-4406743e446c'

def create_and_copy(folder, zip_name):
    zip_path = os.path.join(folder, zip_name)
    if os.path.exists(zip_path):
        os.remove(zip_path)
    
    with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for root, dirs, files in os.walk(folder):
            for file in files:
                if file == zip_name:
                    continue
                full_path = os.path.join(root, file)
                rel_path = os.path.relpath(full_path, folder)
                zipf.write(full_path, rel_path)
    
    size_mb = os.path.getsize(zip_path) / (1024 * 1024)
    print(f'Created {zip_path} ({size_mb:.2f} MB)')
    
    dst = os.path.join(art_dir, zip_name)
    shutil.copy2(zip_path, dst)
    print(f'Copied to artifact directory: {dst}')

create_and_copy('paper_latex_nature_methods', 'AETHER_RAMI_Nature_Methods_Submission_Package.zip')
create_and_copy('paper_latex_nmi', 'AETHER_RAMI_NMI_Submission_Package.zip')

print('All previews and ZIP packages updated successfully!')
